prompt.content:
Here is my flatbuffer data:

namespace goku.apiv2.lmdb.types;

table WebACL {
 owner:string (id: 0);
 payerToken:string (id: 1);
 defaultAction:DefaultAction (id: 3);
 rules:[Rule] (id: 4);
 visibilityConfig: VisibilityConfig (id: 5);
 isolationStatus:IsolationStatus (id: 6);
 version:int (id: 7);
 changeNumber:long (id: 8);
 wcuCapacity:long (id: 9);
 customResponseBodies: [CustomResponseBody] (id: 10);
 labelNamespace: string (id: 11);
 globalCaptchaConfig: CaptchaConfig (id: 12);
 oversizeFieldsHandlingCompliant:bool (id: 13);
 globalChallengeConfig: ChallengeConfig (id: 14);
 tokenDomains: [string] (id: 15);
 associationConfig: AssociationConfig (id: 16);
}

table AssociationConfig {
 requestBodyAssociatedResourceTypeConfig: [RequestBodyAssociatedResourceTypeConfig] (id: 0);
}

table RequestBodyAssociatedResourceTypeConfig {
 associatedResourceType: AssociatedResourceType (id: 0);
 defaultSizeInspectionLimit: SizeInspectionLimit (id: 1);
}

enum AssociatedResourceType: int {
 CLOUDFRONT = 0,
 APPLICATION\_LOAD\_BALANCER = 1,
 API\_GATEWAY = 2,
 APPSYNC = 3,
 COGNITO\_USER\_POOL = 4
}

enum SizeInspectionLimit: int {
 KB\_8 = 0,
 KB\_16 = 1,
 KB\_32 = 2,
 KB\_64 = 3
}

response:
BodyAssociatedResourceTypeConfig {
 type:string;
 }

table DefaultAction {
 action:string; // can be "ALLOW" or "DENY"
}

table Rule {
 priority: int;
 url: string;
 method: Method;
 requestHeaders: [RequestHeader];
 requestParameters: [RequestParameter];
 requestQueryParameters: [RequestQueryParameter];
 responseParameters: [ResponseParameter];
}

table ResponseParameter {
 name:string;
 value:string;
}
Table: RequestHeader, RequestParameter and RequestQueryParameter have the same structure. They each contain:
- name of type string
- value of type string

I want to write a query that will return all rule objects in the web acl table with a specific URL and method.

Can you help me with this? I don't know how to do it with Flatbuffers, but if there's no way to do it using FlatBuffers, please let me know. If you can show an example solution, I would appreciate that. Thanks!
